(function(){var loadHandler=window['sl_{73A53C97-72DA-45CF-9CFF-054D6C4F2812}'];loadHandler&&loadHandler(45, '<div id="spr0_104d2dbd"><div id="spr1_104d2dbd" class="kern slide"><img id="img4_104d2dbd" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_104d2dbd" style="left:986.15px;top:648.5px;"><div id="spr4_104d2dbd"><img id="img0_104d2dbd" src="data:image/png;base64," width="273.75" height="62.25" alt="" style="left:0.06px;top:-0.094px;"/></div></div></div><div id="spr2_104d2dbd" class="kern slide"><div id="spr5_104d2dbd" style="left:160px;top:0px;"><div id="spr6_104d2dbd"><img id="img1_104d2dbd" src="data:image/png;base64," width="794.25" height="709.5" alt="" style="left:0.115px;top:0.073px;"/></div></div><div id="spr7_104d2dbd" style="left:740.25px;top:261.75px;"><img id="img2_104d2dbd" src="data:image/png;base64," width="138" height="51.75" alt=""/></div><div id="spr8_104d2dbd" style="left:551.25px;top:638.25px;"><img id="img3_104d2dbd" src="data:image/png;base64," width="303.75" height="45" alt=""/></div><div id="svg0_104d2dbd" style="left:1102.46px;top:633.693px;"><svg width="154" height="38" viewBox="0 0 154 38"><path fill="#fee599" d="M0,0 h153.6 v37.44 h-153.6 Z"/></svg></div><div id="spr9_104d2dbd" style="left:1102.46px;top:633.693px;"><div style="width:0px;"><span id="txt0_104d2dbd" class="nokern relpos" data-width="66.201172" style="left:9.598px;top:4.764px;">Book A  </span> <span id="txt1_104d2dbd" class="nokern relpos" data-width="62.023438" style="left:9.592px;top:1.931px;">Page 8</span></div></div><div id="svg1_104d2dbd" style="left:931.404px;top:79.549px;"><svg width="344" height="267" viewBox="0 0 344 267"><path fill="#e2f0d9" d="M0,0 h343.68 v266.302 h-343.68 Z"/></svg></div><div id="spr10_104d2dbd" style="left:931.404px;top:79.549px;"><div style="width:0px;"><span id="txt2_104d2dbd" class="nokern" data-width="307.580719" style="left:9.6px;top:6.423px;">The person could still feel the hammer</span></div><div style="width:0px;"><span id="txt3_104d2dbd" class="nokern" data-width="323.276031" style="left:9.6px;top:31.956px;">strike (sensory neurons working), but his</span></div><div style="width:0px;"><span id="txt4_104d2dbd" class="nokern" data-width="314.024719" style="left:9.6px;top:57.489px;">calf muscle did not contract, indicating</span></div><div style="width:0px;"><span id="txt5_104d2dbd" class="nokern relpos" data-width="153.580719" style="left:9.6px;top:83.023px;">a problem with the </span> <span id="txt6_104d2dbd" class="nokern relpos" data-width="127.731766" style="left:9.593px;top:83.023px;">motor pathway</span> <span id="txt7_104d2dbd" class="nokern relpos" style="left:9.587px;top:83.023px;">.</span></div><div style="width:0px;"><span id="txt8_104d2dbd" class="nokern" data-width="304.819000" style="left:9.6px;top:108.556px;">Structures 3 (the interneuron or motor</span></div><div style="width:0px;"><span id="txt9_104d2dbd" class="nokern" data-width="299.979156" style="left:9.6px;top:134.089px;">neuron connection in the spinal cord)</span></div><div style="width:0px;"><span id="txt10_104d2dbd" class="nokern" data-width="306.350250" style="left:9.6px;top:159.623px;">and 4 (the motor neuron leading to the</span></div><div style="width:0px;"><span id="txt11_104d2dbd" class="nokern" data-width="322.993469" style="left:9.6px;top:185.156px;">muscle) are responsible for initiating the</span></div><div style="width:0px;"><span id="txt12_104d2dbd" class="nokern" data-width="282.223938" style="left:9.6px;top:210.689px;">muscle response, so damage there</span></div><div style="width:0px;"><span id="txt13_104d2dbd" class="nokern" data-width="295.421875" style="left:9.6px;top:236.223px;">would prevent the reflex contraction.</span></div></div><div id="svg2_104d2dbd" style="left:912.38px;top:429.203px;"><svg width="344" height="189" viewBox="0 0 344 189"><path fill="#e2f0d9" d="M0,0 h343.68 v188.745 h-343.68 Z"/></svg></div><div id="spr11_104d2dbd" style="left:912.38px;top:429.203px;"><div style="width:0px;"><span id="txt14_104d2dbd" class="nokern relpos" data-width="50.813801" style="left:9.6px;top:6.746px;">CMT1</span> <span id="txt15_104d2dbd" class="nokern relpos" data-width="96.496094" style="left:9.593px;top:6.746px;"> affects the </span> <span id="txt16_104d2dbd" class="nokern relpos" data-width="124.486977" style="left:9.587px;top:6.746px;">myelin sheath</span></div><div style="width:0px;"><span id="txt17_104d2dbd" class="nokern relpos" data-width="108.910156" style="left:9.6px;top:32.28px;">(structure 3)</span> <span id="txt18_104d2dbd" class="nokern relpos" data-width="159.778641" style="left:9.593px;top:32.28px;">, which disrupts the</span></div><div style="width:0px;"><span id="txt19_104d2dbd" class="nokern" data-width="260.467438" style="left:9.6px;top:57.813px;">insulation needed for fast nerve</span></div><div style="width:0px;"><span id="txt20_104d2dbd" class="nokern relpos" data-width="162.868484" style="left:9.6px;top:83.346px;">transmission, while </span> <span id="txt21_104d2dbd" class="nokern relpos" data-width="50.813801" style="left:9.593px;top:83.346px;">CMT2</span> <span id="txt22_104d2dbd" class="nokern relpos" data-width="91.309891" style="left:9.587px;top:83.346px;"> affects the</span></div><div style="width:0px;"><span id="txt23_104d2dbd" class="nokern relpos" data-width="157.664062" style="left:9.6px;top:108.88px;">axon (structure 2)</span> <span id="txt24_104d2dbd" class="nokern relpos" data-width="117.240883" style="left:9.593px;top:108.88px;">, impairing the</span></div><div style="width:0px;"><span id="txt25_104d2dbd" class="nokern" data-width="296.761719" style="left:9.6px;top:134.413px;">actual conduction of nerve impulses</span></div><div style="width:0px;"><span id="txt26_104d2dbd" class="nokern" data-width="145.304688" style="left:9.6px;top:159.946px;">along the neuron.</span></div></div><div id="spr12_104d2dbd" style="left:1224.769px;"><div id="svg3_104d2dbd" style="left:5.031px;top:4.251px;"><svg width="47" height="28" viewBox="0 0 47 28"><path fill="#c00000" d="M0,0 h46.08 v27.429 h-46.08 Z"/></svg></div><div id="svg4_104d2dbd" style="left:0px;top:0px;"><svg width="65" height="28" viewBox="0 0 65 28"><path fill="none" d="M0,0 h64.174 v27.433 h-64.174 Z"/></svg></div><div id="spr13_104d2dbd"><div style="width:0px;"><span id="txt27_104d2dbd" class="nokern" data-width="42.155083" style="left:9.598px;top:2.268px;">END</span></div></div></div></div></div>', '{"s":[]}');})();